'use strict';

// Draws the route on an SVG map and moves the vehicle (shinkansen / airplane) along it.
// Map shapes come from map-data.js (generated by tools/build-map.mjs).
const TravelMap = (() => {
  const NS = 'http://www.w3.org/2000/svg';
  const PLANE_PATH = 'M21 16v-2l-8-5V3.5c0-.83-.67-1.5-1.5-1.5S10 2.67 10 3.5V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5l8 2.5z';
  const TRAIN_BODY = 'M2 8a4 4 0 0 1 4-4h21c8 0 14 6 19 11v3a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2z';
  const TRAIN_WINDOWS = 'M7 8h5v4H7zM14 8h5v4h-5zM21 8h5v4h-5zM28.5 8H31c2.5 0 4.7 1.7 6.5 4h-9z';

  // how wide the closest zoom is, as a share of the whole map
  const MIN_ZOOM_WIDTH = { japan: 0.22, world: 0.14 };
  // how much the route bends (airplane routes are drawn as arcs)
  const CURVE = { japan: 0, world: 0.12 };

  let host = null;
  let svg = null;
  let route = null;
  let cam = null; // current camera { x, y, w, h } in map units
  let hostWidth = 0;
  let frameId = 0;
  let lastDraw = 0;
  let settled = true;
  let view = { getKm: () => 0, goalName: '', cameraMode: 'leg', running: false };

  const clamp = (v, lo, hi) => Math.min(Math.max(v, lo), hi);

  function svgEl(tag, attrs = {}, parent = null) {
    const node = document.createElementNS(NS, tag);
    for (const [name, value] of Object.entries(attrs)) node.setAttribute(name, value);
    if (parent) parent.append(node);
    return node;
  }

  // ---------- geometry ----------
  function makeLeg(a, b, bend) {
    const mx = (a[0] + b[0]) / 2;
    const my = (a[1] + b[1]) / 2;
    const len = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1;
    // bulge to the north (up on the screen)
    let nx = -(b[1] - a[1]) / len;
    let ny = (b[0] - a[0]) / len;
    if (ny > 0) {
      nx = -nx;
      ny = -ny;
    }
    return { a, b, c: [mx + nx * len * bend, my + ny * len * bend], bend };
  }

  function pointOn(leg, t) {
    const u = 1 - t;
    return [
      u * u * leg.a[0] + 2 * u * t * leg.c[0] + t * t * leg.b[0],
      u * u * leg.a[1] + 2 * u * t * leg.c[1] + t * t * leg.b[1],
    ];
  }

  function tangentOn(leg, t) {
    return [
      2 * (1 - t) * (leg.c[0] - leg.a[0]) + 2 * t * (leg.b[0] - leg.c[0]),
      2 * (1 - t) * (leg.c[1] - leg.a[1]) + 2 * t * (leg.b[1] - leg.c[1]),
    ];
  }

  const fmt = (n) => Math.round(n * 10) / 10;

  function legPath(leg) {
    return leg.bend === 0
      ? `M${fmt(leg.a[0])} ${fmt(leg.a[1])}L${fmt(leg.b[0])} ${fmt(leg.b[1])}`
      : `M${fmt(leg.a[0])} ${fmt(leg.a[1])}Q${fmt(leg.c[0])} ${fmt(leg.c[1])} ${fmt(leg.b[0])} ${fmt(leg.b[1])}`;
  }

  // the part of a leg from its start to t
  function partialPath(leg, t) {
    const end = pointOn(leg, t);
    if (leg.bend === 0) return `M${fmt(leg.a[0])} ${fmt(leg.a[1])}L${fmt(end[0])} ${fmt(end[1])}`;
    const cx = leg.a[0] + t * (leg.c[0] - leg.a[0]);
    const cy = leg.a[1] + t * (leg.c[1] - leg.a[1]);
    return `M${fmt(leg.a[0])} ${fmt(leg.a[1])}Q${fmt(cx)} ${fmt(cy)} ${fmt(end[0])} ${fmt(end[1])}`;
  }

  // ---------- building the SVG ----------
  function build() {
    const { data, cities, key } = route;
    host.replaceChildren();
    host.style.aspectRatio = `${data.width} / ${data.height}`;

    svg = svgEl('svg', { viewBox: `0 0 ${data.width} ${data.height}`, preserveAspectRatio: 'xMidYMid meet', 'aria-hidden': 'true' });
    svg.classList.add(`map-${key}`);
    svgEl('rect', { class: 'sea', x: -data.width, y: -data.height, width: data.width * 3, height: data.height * 3 }, svg);
    svgEl('path', { class: 'land', d: data.land }, svg);

    route.legs = [];
    for (let i = 0; i < cities.length - 1; i += 1) {
      route.legs.push(makeLeg(data.points[cities[i].name], data.points[cities[i + 1].name], CURVE[key] || 0));
    }

    svgEl('path', { class: 'route-all', d: route.legs.map(legPath).join('') }, svg);
    route.doneEl = svgEl('path', { class: 'route-done', d: '' }, svg);

    route.cityEls = cities.map((city) => {
      const group = svgEl('g', { class: 'city' }, svg);
      svgEl('circle', { class: 'city-dot', r: 5 }, group);
      const label = svgEl('text', { class: 'city-label', x: 9, y: 4 }, group);
      label.textContent = `${city.emoji} ${city.name}`;
      return { group, label, width: city.name.length * 12 + 30 };
    });

    route.goalEl = svgEl('g', { class: 'goal' }, svg);
    svgEl('circle', { class: 'goal-ring', r: 12 }, route.goalEl);

    const vehicle = svgEl('g', { class: 'vehicle' }, svg);
    route.vehicleEl = vehicle;
    svgEl('circle', { class: 'pulse', r: 20 }, vehicle);
    route.bodyEl = svgEl('g', { class: 'vehicle-body' }, vehicle);
    if (route.vehicle === 'plane') {
      svgEl('path', { d: PLANE_PATH }, route.bodyEl);
    } else {
      svgEl('path', { d: TRAIN_BODY }, route.bodyEl);
      svgEl('path', { class: 'train-win', d: TRAIN_WINDOWS }, route.bodyEl);
    }

    host.append(svg);
    cam = null;
  }

  // ---------- camera ----------
  function cameraTarget(leg) {
    const { width: W, height: H } = route.data;
    if (view.cameraMode === 'all') return { x: 0, y: 0, w: W, h: H };

    const aspect = W / H;
    const mid = pointOn(leg, 0.5);
    const xs = [leg.a[0], leg.b[0], mid[0]];
    const ys = [leg.a[1], leg.b[1], mid[1]];
    const minX = Math.min(...xs);
    const maxX = Math.max(...xs);
    const minY = Math.min(...ys);
    const maxY = Math.max(...ys);

    let w = Math.max((maxX - minX) * 2.4, (maxY - minY) * 2.4 * aspect, W * (MIN_ZOOM_WIDTH[route.key] || 0.2));
    w = Math.min(w, W);
    const h = w / aspect;
    return {
      x: clamp((minX + maxX) / 2 - w / 2, 0, W - w),
      y: clamp((minY + maxY) / 2 - h / 2, 0, H - h),
      w,
      h,
    };
  }

  function moveCamera(target) {
    if (!cam) {
      cam = { ...target };
      settled = true;
      return;
    }
    const keys = ['x', 'y', 'w', 'h'];
    let far = false;
    for (const k of keys) {
      const diff = target[k] - cam[k];
      if (Math.abs(diff) > 0.15) {
        cam[k] += diff * 0.14;
        far = true;
      } else {
        cam[k] = target[k];
      }
    }
    settled = !far;
  }

  // ---------- drawing ----------
  function draw(km) {
    const { cities, legs, data } = route;
    const total = cities[cities.length - 1].km;
    const distance = clamp(km, 0, total);

    let i = 0;
    while (i < legs.length - 1 && distance >= cities[i + 1].km) i += 1;
    const leg = legs[i];
    const t = clamp((distance - cities[i].km) / (cities[i + 1].km - cities[i].km), 0, 1);
    const position = pointOn(leg, t);
    const [tx, ty] = tangentOn(leg, t);

    route.doneEl.setAttribute('d', legs.slice(0, i).map(legPath).join('') + partialPath(leg, t));

    moveCamera(cameraTarget(leg));
    svg.setAttribute('viewBox', `${cam.x} ${cam.y} ${cam.w} ${cam.h}`);
    svg.classList.toggle('running', view.running);

    const pxPerUnit = hostWidth > 0 ? hostWidth / cam.w : 1;
    const unit = 1 / pxPerUnit; // map units per screen pixel: keeps markers the same size on screen
    const toScreen = (p) => [(p[0] - cam.x) * pxPerUnit, (p[1] - cam.y) * pxPerUnit];
    const hostHeight = hostWidth * (data.height / data.width);

    // vehicle
    route.vehicleEl.setAttribute('transform', `translate(${position[0]} ${position[1]}) scale(${unit})`);
    if (route.vehicle === 'plane') {
      const deg = (Math.atan2(ty, tx) * 180) / Math.PI + 90;
      route.bodyEl.setAttribute('transform', `rotate(${deg}) scale(${34 / 24}) translate(-12 -12)`);
    } else {
      const flip = tx < 0 ? -1 : 1;
      const tilt = clamp((Math.atan2(ty, Math.abs(tx)) * 180) / Math.PI, -25, 25) * flip;
      route.bodyEl.setAttribute('transform', `rotate(${tilt}) scale(${flip * 0.96} 0.96) translate(-24 -12)`);
    }

    // cities, labelled in priority order and skipped when they would overlap
    const goalIndex = cities.findIndex((c) => c.name === view.goalName);
    const priority = [goalIndex, i, i + 1, 0, ...cities.map((_, n) => n)];
    const shown = new Set();
    const rects = [];
    for (const n of priority) {
      if (n < 0 || shown.has(n)) continue;
      shown.add(n);
      const p = data.points[cities[n].name];
      const [sx, sy] = toScreen(p);
      const entry = route.cityEls[n];
      const onScreen = sx > -20 && sx < hostWidth + 20 && sy > -20 && sy < hostHeight + 20;
      entry.group.style.display = onScreen ? '' : 'none';
      if (!onScreen) continue;

      entry.group.setAttribute('transform', `translate(${p[0]} ${p[1]}) scale(${unit})`);
      entry.group.classList.toggle('reached', distance >= cities[n].km);

      const rect = { x: sx + 9, y: sy - 9, w: entry.width, h: 18 };
      const fits = sx + 9 + entry.width < hostWidth;
      if (!fits) {
        rect.x = sx - 9 - entry.width;
        entry.label.setAttribute('x', -9);
        entry.label.setAttribute('text-anchor', 'end');
      } else {
        entry.label.setAttribute('x', 9);
        entry.label.setAttribute('text-anchor', 'start');
      }
      const overlaps = rects.some((r) => rect.x < r.x + r.w && rect.x + rect.w > r.x && rect.y < r.y + r.h && rect.y + rect.h > r.y);
      entry.label.style.display = overlaps ? 'none' : '';
      if (!overlaps) rects.push(rect);
    }

    // goal marker
    if (goalIndex >= 0) {
      const gp = data.points[cities[goalIndex].name];
      route.goalEl.style.display = '';
      route.goalEl.setAttribute('transform', `translate(${gp[0]} ${gp[1]}) scale(${unit})`);
    } else {
      route.goalEl.style.display = 'none';
    }
  }

  // ---------- frame loop ----------
  function schedule() {
    if (!frameId) frameId = requestAnimationFrame(frame);
  }

  function frame(now) {
    frameId = 0;
    if (!svg || !route) return;
    // while only the vehicle creeps along, redrawing ~12 times a second is plenty
    if (settled && view.running && now - lastDraw < 80) {
      schedule();
      return;
    }
    lastDraw = now;
    draw(view.getKm());
    if (!settled || view.running) schedule();
  }

  // ---------- public API ----------
  function init(element) {
    host = element;
    if (!window.MAP_DATA) {
      host.textContent = '地図データを読み込めませんでした。';
      host = null;
      return;
    }
    hostWidth = host.clientWidth;
    if (typeof ResizeObserver === 'function') {
      new ResizeObserver(() => {
        hostWidth = host.clientWidth;
        schedule();
      }).observe(host);
    }
  }

  // next: { key, cities, vehicle: 'plane' | 'train' }
  function setRoute(next) {
    if (!host || !window.MAP_DATA || !window.MAP_DATA[next.key]) return;
    const same = route && route.key === next.key;
    route = { ...(same ? route : {}), ...next, data: window.MAP_DATA[next.key] };
    if (!same) build();
    schedule();
  }

  function setView(next) {
    view = { ...view, ...next };
    schedule();
  }

  return { init, setRoute, setView, invalidate: schedule };
})();
